const RAW_VOCABULARY_LIST: VocabularyWord[] = [
  ...VOCAB_PART_1,
  ...VOCAB_PART_2,
  ...VOCAB_PART_3,
  ...VOCAB_PART_4,
  ...VOCAB_PART_5,
  ...VOCAB_PART_6,
  ...VOCAB_PART_7,
  ...VOCAB_PART_8,
  ...VOCAB_PART_9,
  ...VOCAB_PART_10
];

export const VOCABULARY_LIST: VocabularyWord[] = (RAW_VOCABULARY_LIST as VocabularyWord[]).filter((v, index, self) =>
  index === self.findIndex((t) => t.word.trim().toLowerCase() === v.word.trim().toLowerCase())
);

function generateAllCourseStories(vocabList: VocabularyWord[]): PracticeStory[] {
  const categoryMap = new Map<string, VocabularyWord[]>();

  vocabList.forEach((v) => {
    const cat = v.category || 'مفردات عامة';
    if (!categoryMap.has(cat)) {
      categoryMap.set(cat, []);
    }
    categoryMap.get(cat)!.push(v);
  });

  const stories: PracticeStory[] = [];
  let idIndex = 1;

  categoryMap.forEach((words, catName) => {
    const chunkSize = 8;
    const totalChunks = Math.ceil(words.length / chunkSize);

    for (let i = 0; i < words.length; i += chunkSize) {
      const chunk = words.slice(i, i + chunkSize);
      const partNum = Math.floor(i / chunkSize) + 1;
      const titleSuffix = totalChunks > 1 ? ` (المجموعة ${partNum})` : '';

      stories.push({
        id: `course_story_${idIndex++}`,
        titleEn: `${catName} Part ${partNum}`,
        titleAr: `${catName}${titleSuffix}`,
        category: catName,
        difficulty: 'easy',
        sentences: chunk.map((item) => ({
          en: item.word,
          ar: item.arabic,
          keyWords: [item.word]
        }))
      });
    }
  });

  return stories;
}

export const PRACTICE_STORIES: PracticeStory[] = generateAllCourseStories(VOCABULARY_LIST);

